		_this.stop(); // Hentikan timeline agar tidak jalan sendiri
		
		// --- DEKLARASI VARIABEL GLOBAL (Hanya dipanggil sekali di awal) ---
		window.namaPemain = "";
		window.playerNyawa = 3;
