	this.frame_39 = function() {
		var _this = this;
		_this.stop();
		
		// Hapus memori klik sebelumnya (jika ada) agar tidak error double-click
		if (_this.btn_ok) _this.btn_ok.removeAllEventListeners("click");
		
		// Sensor klik tombol OK
		if (_this.btn_ok) {
		    _this.btn_ok.on("click", function() {
		        
		        // Ganti "map_level" dengan nama frame map level kamu yang sebenarnya
		        if (typeof exportRoot !== "undefined") {
		            exportRoot.gotoAndStop("mapLevel");
		        } else if (_this.parent) {
		            _this.parent.gotoAndStop("mapLevel");
		        } else {
		            _this.gotoAndStop("mapLevel");
		        }
		        
		    });
		}
	}
	this.frame_40 = function() {
		var _this = this;
		_this.stop();
		
		// Memori skor
		window.skorPemain = window.skorPemain || 0;
		
		// Paksa reset pilihan di sistem agar kosong setiap masuk soal baru
		var pilihanPemain = "";
		var jawabanBenar = "A"; // GANTI HURUF INI SESUAI JAWABAN BENAR
		
		// Fungsi kembalikan tombol ke normal (alpha 1)
		function resetTombol() {
		    if (_this.btn_a) _this.btn_a.alpha = 1;
		    if (_this.btn_b) _this.btn_b.alpha = 1;
		    if (_this.btn_c) _this.btn_c.alpha = 1;
		    if (_this.btn_d) _this.btn_d.alpha = 1;
		    if (_this.btn_e) _this.btn_e.alpha = 1;
		}
		
		// 1. BERSIHKAN TAMPILAN PUDAR DARI SOAL SEBELUMNYA
		resetTombol(); 
		
		// 2. HAPUS MEMORI KLIK LAMA AGAR TIDAK BOCOR / MENUMPUK
		if (_this.btn_a) _this.btn_a.removeAllEventListeners("click");
		if (_this.btn_b) _this.btn_b.removeAllEventListeners("click");
		if (_this.btn_c) _this.btn_c.removeAllEventListeners("click");
		if (_this.btn_d) _this.btn_d.removeAllEventListeners("click");
		if (_this.btn_e) _this.btn_e.removeAllEventListeners("click");
		if (_this.btn_kunci) _this.btn_kunci.removeAllEventListeners("click");
		
		// 3. PASANG DETEKSI KLIK YANG BARU DAN BERSIH
		if (_this.btn_a) _this.btn_a.on("click", function() { pilihanPemain = "A"; resetTombol(); _this.btn_a.alpha = 0.5; });
		if (_this.btn_b) _this.btn_b.on("click", function() { pilihanPemain = "B"; resetTombol(); _this.btn_b.alpha = 0.5; });
		if (_this.btn_c) _this.btn_c.on("click", function() { pilihanPemain = "C"; resetTombol(); _this.btn_c.alpha = 0.5; });
		if (_this.btn_d) _this.btn_d.on("click", function() { pilihanPemain = "D"; resetTombol(); _this.btn_d.alpha = 0.5; });
		if (_this.btn_e) _this.btn_e.on("click", function() { pilihanPemain = "E"; resetTombol(); _this.btn_e.alpha = 0.5; });
		
		if (_this.btn_kunci) {
		    _this.btn_kunci.on("click", function() {
		        
		        if (pilihanPemain === "") {
		            alert("Anda belum memilih jawaban!");
		            return; 
		        }
		
		        if (pilihanPemain === jawabanBenar) {
		            alert("Selamat, jawaban kamu benar!");
		            window.skorPemain += 20; 
		        } else {
		            alert("Maaf, jawaban kamu salah.");
		        }
		
		        if (typeof exportRoot !== "undefined") {
		            exportRoot.gotoAndStop("inGame1");
		        } else if (_this.parent) {
		            _this.parent.gotoAndStop("inGame1");
		        } else {
		            _this.gotoAndStop("inGame1");
		        }
		    });
		}
	}
